-- Isolated H2 test database only; production uses backend/db/schema.sql.
CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(64) UNIQUE,password_hash VARCHAR(255),password_change_required BOOLEAN NOT NULL DEFAULT FALSE,display_name VARCHAR(80),role VARCHAR(24),account_status VARCHAR(24),phone VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP,reviewed_by BIGINT,review_note VARCHAR(300));
CREATE TABLE api_sessions(token_hash VARCHAR(64) PRIMARY KEY,user_id BIGINT,expires_at TIMESTAMP);
CREATE TABLE routes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,route_name VARCHAR(120),origin_city VARCHAR(80),destination_city VARCHAR(80),route_status VARCHAR(24),data_source VARCHAR(80),version_number INT DEFAULT 1,parent_route_id BIGINT,created_by BIGINT,verified_at TIMESTAMP,verified_by BIGINT);
CREATE TABLE route_segments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,route_id BIGINT,sequence_number INT,from_city VARCHAR(80),to_city VARCHAR(80),road_name VARCHAR(160),road_type VARCHAR(48),distance_km DOUBLE,estimated_minutes DOUBLE,geometry_json VARCHAR(1000000),map_source VARCHAR(80),map_request_json VARCHAR(12000),map_response_reference VARCHAR(512),truck_access_status VARCHAR(24) DEFAULT 'PENDING',truck_evidence_source VARCHAR(160),truck_evidence_reference VARCHAR(512),verified_at TIMESTAMP,verified_by BIGINT, UNIQUE(route_id,sequence_number));
CREATE TABLE vehicles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plate_number VARCHAR(24) UNIQUE,vehicle_type VARCHAR(48),energy_type VARCHAR(24) DEFAULT '柴油',total_weight_tons DOUBLE,length_m DOUBLE,width_m DOUBLE,height_m DOUBLE,axle_count INT,has_etc BOOLEAN DEFAULT FALSE,max_load_tons DOUBLE,fuel_model_liters_per_100km DOUBLE,driver_id BIGINT,vehicle_status VARCHAR(24) DEFAULT 'AVAILABLE',next_service_on DATE);
CREATE TABLE transport_tasks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_code VARCHAR(40) UNIQUE,route_id BIGINT,cargo_description VARCHAR(120),cargo_weight_tons DOUBLE,planned_distance_km DOUBLE,planned_duration_minutes DOUBLE,price_per_km DOUBLE,delivery_deadline TIMESTAMP,task_details VARCHAR(1000),driver_id BIGINT,vehicle_id BIGINT,task_status VARCHAR(32),started_at TIMESTAMP,completed_at TIMESTAMP,source_type VARCHAR(24),demo_mode BOOLEAN DEFAULT FALSE,sample_status VARCHAR(24) DEFAULT 'PENDING_MATCH',exclusion_reason VARCHAR(300),route_difference_recoverable BOOLEAN DEFAULT FALSE,matched_route_json VARCHAR(1000000),matched_city_sequence VARCHAR(10000),created_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE driver_feedback(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_id BIGINT UNIQUE,actual_distance_km DOUBLE,actual_fuel_liters DOUBLE,comment VARCHAR(900));
CREATE TABLE maintenance_records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_id BIGINT,recorded_by BIGINT,description VARCHAR(900),serviced_on DATE,next_service_on DATE);
CREATE TABLE audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_user_id BIGINT,action VARCHAR(80),entity_type VARCHAR(48),entity_id VARCHAR(80),details_json VARCHAR(12000));
CREATE TABLE system_config(id INT PRIMARY KEY,version_number BIGINT,config_json VARCHAR(20000),updated_by BIGINT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE actual_route_analyses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_id BIGINT,sample_status VARCHAR(24),snapshot_json VARCHAR(1000000),created_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE optimization_evaluations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_route_id BIGINT,candidate_route_id BIGINT,recommendation_status VARCHAR(48),snapshot_json VARCHAR(1000000),created_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE route_optimization_runs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,origin_city VARCHAR(80),destination_city VARCHAR(80),plan_route_id BIGINT,candidate_route_id BIGINT,sample_count INT,recommendation_status VARCHAR(48),estimate_source VARCHAR(160),time_min DOUBLE,time_max DOUBLE,distance_min DOUBLE,distance_max DOUBLE,fuel_min DOUBLE,fuel_max DOUBLE,time_weight DOUBLE,distance_weight DOUBLE,fuel_weight DOUBLE,time_score DOUBLE,distance_score DOUBLE,fuel_score DOUBLE,composite_score DOUBLE,selection_reason VARCHAR(20000));
